if doc.shop_route:
    SR = frappe.get_doc("Shop Route",doc.shop_route)
    for row in SR.table_2:
        row.distributor_invoice_no = doc.name
        row.di_created = 1
    SR.save()

if doc.shop_route:
    SR = frappe.get_doc("Shop Route",doc.shop_route)
    for row in SR.table_2:
        if row.customer_name == doc.customer_name:
            row.distributor_invoice_no = doc.name
            row.di_created = 1

    SR.save()

if doc.party_type == "Customer":
    mobile = frappe.db.get_value('Customer', doc.party, 'customer_mobile_no')
    doc.phone_no = mobile

for row in doc.accounts:
    if row.party_type:
        if row.party_type == "Customer":
            subject = frappe.db.get_value('Customer',row.party, 'customer_name')
            row.party_name = subject
        if row.party_type == "Supplier":
            subject = frappe.db.get_value('Supplier', row.party, 'supplier_name')
            row.party_name = subject
        if row.party_type == "Employee":
            subject = frappe.db.get_value('Employee', row.party, 'employee_name')
            row.party_name = subject
